def find_crosses(g):
    H=len(g);W=len(g[0]); out=[]
    for r in range(1,H-1):
        for c in range(1,W-1):
            v=g[r][c]
            nb={g[r-1][c],g[r+1][c],g[r][c-1],g[r][c+1]}
            if len(nb)==1 and next(iter(nb))!=v: out.append((r,c,v))
    return out

def apply(g, order, mode='stopatnonzero'):
    H=len(g); W=len(g[0])
